<template>
    <div>
        <Head title="Datatables" />

        <Card title="Datatable Playground" icon="tune" card-header-class="card-header-primary">
            <p>Explore the component using the employee data from the HTML template. Change the options, then apply them to restart the table.</p>
            <form @submit.prevent="applySettings">
                <div class="row gy-3">
                    <div class="md:col-6 lg:col-4">
                        <label for="datatable-title">Card title <code>cardTitle</code></label>
                        <input id="datatable-title" v-model="settings.cardTitle" class="form-control" type="text">
                    </div>
                    <div class="md:col-6 lg:col-4">
                        <label for="datatable-icon">Material icon <code>cardIcon</code></label>
                        <input id="datatable-icon" v-model="settings.cardIcon" class="form-control" type="text" placeholder="people">
                    </div>
                    <div v-for="control in selectControls" :key="control.key" class="md:col-6 lg:col-4">
                        <span :id="`datatable-${control.key}-label`" class="d-block mb-1">
                            {{ control.label }} <code>{{ control.prop }}</code>
                        </span>
                        <Select42
                            v-model="settings[control.key]"
                            class="w-100"
                            :options="control.options"
                            :aria-labelledby="`datatable-${control.key}-label`"
                            :show-search="false"
                            :allow-clear="false"
                        />
                    </div>
                </div>
                <div class="row gy-2 mt-3">
                    <div v-for="control in toggleControls" :key="control.key" class="md:col-6 lg:col-4">
                        <Toggle :id="`datatable-${control.key}`" v-model="settings[control.key]" :label="control.label" />
                        <small><code>{{ control.key }}</code></small>
                    </div>
                </div>
                <div class="row gy-3 mt-3">
                    <div class="md:col-6">
                        <span id="datatable-office-label" class="d-block mb-1">Office filter <code>requestQueryParams.office</code></span>
                        <Select42 v-model="settings.office" class="w-100" :options="officeOptions" aria-labelledby="datatable-office-label" :show-search="false" :allow-clear="false" />
                    </div>
                </div>
                <fieldset class="mt-3">
                    <legend class="h4">Columns</legend>
                    <p>Hidden columns remain in the request. Search and sorting permissions are configured independently.</p>
                    <div v-for="(column, index) in settings.columns" :key="column.data" class="row gy-2 mb-3 align-items-center">
                        <div class="md:col-3">
                            <label :for="`datatable-column-label-${index}`">{{ column.data }}</label>
                            <input :id="`datatable-column-label-${index}`" v-model="column.displayName" class="form-control" type="text" required>
                        </div>
                        <div class="md:col-2">
                            <label :for="`datatable-column-width-${index}`">Width</label>
                            <input :id="`datatable-column-width-${index}`" v-model="column.width" class="form-control" type="text" placeholder="auto, 120px, 20%">
                        </div>
                        <div v-for="property in ['visible', 'searchable', 'sortable']" :key="property" class="md:col-2">
                            <Toggle :id="`datatable-column-${index}-${property}`" v-model="column[property]" :label="property" />
                        </div>
                    </div>
                    <p v-if="!hasVisibleColumn" class="fg-danger" role="status">Keep at least one column visible.</p>
                </fieldset>
                <p class="mt-2 mb-0">Custom rendering formats dates and office badges. Conditional colors highlight ages below 30 and ages 60 or above.</p>
                <div class="d-flex flex-wrap gap-2 mt-3">
                    <button type="submit" class="btn btn-primary" :disabled="!hasVisibleColumn">Apply options</button>
                    <button type="button" class="btn btn-default" @click="resetSettings">Reset</button>
                </div>
                <small>Applying options resets searches, sorting, pagination, and selected rows.</small>
            </form>
        </Card>

        <DatatableCard
            :key="tableVersion"
            ref="datatable"
            v-bind="tableProps"
            @row-click="onRowClick"
            @demo-inspect="onInspect"
            @demo-flag="onFlag"
        >
            <template v-if="applied.customHeader" #header>
                <span class="fg-2 me-2">Employee directory</span>
            </template>
            <template v-if="applied.customToolbar" #actions>
                <li>
                    <button type="button" class="vdt-button" :disabled="!applied.selectableRows" @click="showSelectedRows">Selected IDs</button>
                </li>
            </template>
            <template v-if="applied.bodyHint" #default>
                <p class="mb-3">Demo data from the HTML template. Office: {{ applied.office || 'All offices' }}. Row actions only display feedback.</p>
            </template>
        </DatatableCard>
        <div class="d-flex flex-wrap align-items-center gap-2 mb-3">
            <button type="button" class="btn btn-primary btn-sm" @click="loadEmployees">Load / reload data</button>
            <small v-if="!applied.loadDataOnInit">Automatic loading is disabled. Use this button to load the employees.</small>
        </div>
        <p role="status" aria-live="polite">{{ rowFeedback }}</p>

        <Card title="Vue Configuration" icon="code" card-header-class="card-header-info">
            <p>This example follows the applied settings, including callbacks and slots. The data URL uses this scaffold’s demo endpoint.</p>
            <button type="button" class="btn btn-primary btn-sm" @click="copyConfiguration">Copy example</button>
            <p role="status" aria-live="polite">{{ copyFeedback }}</p>
            <textarea ref="configuration" class="form-control font-monospace" aria-label="Datatable Vue configuration example" :value="configurationExample" rows="18" wrap="off" readonly spellcheck="false"></textarea>
        </Card>
    </div>
</template>

<script>
import { Head } from '@inertiajs/vue3';
import Select42 from '@sulzanoks/select42';
import DatatableCard from '@sulzanoks/vue-datatable';
import Card from '@scaffold/components/Card.vue';
import Toggle from '@scaffold/components/Toggle.vue';
import { datatablesData } from '@app/routes/demo/tables';

const defaultColumns = () => [
    { data: 'name', displayName: 'Name' },
    { data: 'position', displayName: 'Position' },
    { data: 'office', displayName: 'Office' },
    { data: 'age', displayName: 'Age' },
    { data: 'start_date', displayName: 'Start date' },
].map(column => ({ ...column, name: column.data, visible: true, searchable: true, sortable: true, width: '' }));

function escapeHtml(value) {
    return String(value).replace(/[&<>"']/g, character => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[character]);
}

function formatStartDate(row, locale) {
    const [year, month, day] = row.start_date.split('/').map(Number);
    return new Intl.DateTimeFormat(locale, { day: 'numeric', month: 'short', year: 'numeric', timeZone: 'UTC' })
        .format(new Date(Date.UTC(year, month - 1, day)));
}

function configuredColumns(settings) {
    const locale = settings.locale;
    return settings.columns.map(column => {
        const result = { ...column };
        if (!result.width.trim()) {
            delete result.width;
        }
        if (settings.customRender && column.data === 'office') {
            result.render = row => `<span class="badge theme-info theme-subtle">${escapeHtml(row.office)}</span>`;
        }
        if (settings.customRender && column.data === 'start_date') {
            result.render = row => formatStartDate(row, locale);
        }
        if (settings.conditionalColors && column.data === 'age') {
            result.classes = [{ max: 29, class: 'fg-info fw-bold' }, { min: 60, class: 'fg-warning fw-bold' }];
        }
        return result;
    });
}

const defaultSettings = () => ({
    cardTitle: 'Employees',
    cardIcon: 'people',
    color: 'primary',
    locale: 'en',
    pageLength: '10',
    sortColumn: '0',
    sortDirection: 'asc',
    showHeader: true,
    advancedSearch: false,
    selectableRows: false,
    clickableRows: false,
    loadDataOnInit: true,
    office: '',
    columns: defaultColumns(),
    customRender: false,
    conditionalColors: false,
    showActions: false,
    customHeader: false,
    customToolbar: false,
    bodyHint: false,
});

export default {
    name: 'DatatablesDemo',
    components: { Card, DatatableCard, Head, Select42, Toggle },
    layout: { pageTitle: 'Datatables' },
    data() {
        return {
            dataUrl: datatablesData.url(),
            settings: defaultSettings(),
            applied: defaultSettings(),
            tableVersion: 0,
            rowFeedback: '',
            copyFeedback: '',
            officeOptions: [{ value: '', text: 'All offices' }, ...['Edinburgh', 'Tokyo', 'San Francisco', 'New York', 'London', 'Sidney', 'Singapore'].map(value => ({ value, text: value }))],
            selectControls: [
                {
                    key: 'color', label: 'Icon color', prop: 'cardIconStyle',
                    options: ['primary', 'info', 'success', 'warning', 'danger', 'rose'].map(value => ({ value, text: value })),
                },
                {
                    key: 'locale', label: 'Interface language', prop: 'locale',
                    options: [{ value: 'en', text: 'English' }, { value: 'lv', text: 'Latviešu' }, { value: 'ru', text: 'Русский' }],
                },
                {
                    key: 'pageLength', label: 'Initial page size', prop: 'pageLength',
                    options: ['10', '25', '50', '100'].map(value => ({ value, text: value })),
                },
                {
                    key: 'sortColumn', label: 'Initial sort column', prop: 'order.column',
                    options: ['Name', 'Position', 'Office', 'Age', 'Start date'].map((text, index) => ({ value: String(index), text })),
                },
                {
                    key: 'sortDirection', label: 'Initial sort direction', prop: 'order.dir',
                    options: [{ value: 'asc', text: 'Ascending' }, { value: 'desc', text: 'Descending' }],
                },
            ],
            toggleControls: [
                { key: 'showHeader', label: 'Show header and toolbar' },
                { key: 'advancedSearch', label: 'Per-column search' },
                { key: 'selectableRows', label: 'Row selection' },
                { key: 'clickableRows', label: 'Clickable rows' },
                { key: 'loadDataOnInit', label: 'Load data automatically' },
                { key: 'customRender', label: 'Formatted dates and office badges' },
                { key: 'conditionalColors', label: 'Conditional age colors' },
                { key: 'showActions', label: 'Inspect / Flag row actions' },
                { key: 'customHeader', label: 'Custom header slot' },
                { key: 'customToolbar', label: 'Custom toolbar actions slot' },
                { key: 'bodyHint', label: 'Custom body slot' },
            ],
        };
    },
    computed: {
        hasVisibleColumn() {
            return this.settings.columns.some(column => column.visible);
        },
        tableProps() {
            const columnIndex = Number(this.applied.sortColumn);
            return {
                url: this.dataUrl,
                columns: configuredColumns(this.applied),
                cardTitle: this.applied.cardTitle,
                cardIcon: this.applied.cardIcon,
                cardIconStyle: 'danger',
                locale: this.applied.locale,
                pageLength: Number(this.applied.pageLength),
                order: this.applied.columns[columnIndex].sortable ? [{ column: columnIndex, dir: this.applied.sortDirection }] : [],
                showHeader: this.applied.showHeader,
                advancedSearch: this.applied.advancedSearch,
                selectableRows: this.applied.selectableRows,
                clickableRows: this.applied.clickableRows,
                loadDataOnInit: this.applied.loadDataOnInit,
                requestQueryParams: this.applied.office ? { office: this.applied.office } : {},
                actions: this.applied.showActions ? [
                    { emit: 'demo-inspect', icon: 'visibility', label: 'Inspect', class: 'fg-info' },
                    { emit: 'demo-flag', icon: 'flag', label: 'Flag', class: 'fg-warning' },
                ] : [],
            };
        },
        configurationExample() {
            const columns = this.tableProps.columns.map(column => ({
                ...column,
                ...(column.render ? { render: column.data === 'office' ? '__office_renderer__' : '__date_renderer__' } : {}),
            }));
            const serialized = JSON.stringify({ ...this.tableProps, columns, url: '__data_url__' }, null, 4)
                .replace('"__data_url__"', 'datatablesData.url()')
                .replace('"__office_renderer__"', 'row => renderOffice(row)')
                .replace('"__date_renderer__"', 'row => formatStartDate(row, locale)');
            const lines = [
                '<template>',
                '    <div>',
                '        <DatatableCard ref="datatable" v-bind="datatableProps" @row-click="showEmployee" @demo-inspect="showEmployee" @demo-flag="showEmployee">',
            ];
            if (this.applied.customHeader) {
                lines.push('            <template #header><span class="fg-2 me-2">Employee directory</span></template>');
            }
            if (this.applied.customToolbar) {
                lines.push('            <template #actions><li><button type="button" class="vdt-button" :disabled="!datatableProps.selectableRows" @click="showSelectedRows">Selected IDs</button></li></template>');
            }
            if (this.applied.bodyHint) {
                lines.push('            <p>Demo data from the HTML template. Row actions only display feedback.</p>');
            }
            lines.push(
                '        </DatatableCard>',
                '        <button type="button" class="btn btn-primary" @click="$refs.datatable.loadData()">Load / reload data</button>',
                '        <p role="status">{{ feedback }}</p>',
                '    </div>',
                '</template>',
                '',
                '<script>',
                "import DatatableCard from '@sulzanoks/vue-datatable';",
                "import '@sulzanoks/vue-datatable/dist/style.css';",
                "import { datatablesData } from '@app/routes/demo/tables';",
                `const locale = ${JSON.stringify(this.applied.locale)};`,
                ...(this.applied.customRender ? [
                    'function renderOffice(row) {',
                    `    const entities = ${JSON.stringify({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })};`,
                    String.raw`    const office = String(row.office).replace(/[&<>"']/g, character => entities[character]);`,
                    '    return `<span class="badge theme-info theme-subtle">${office}</span>`;',
                    '}',
                    'function formatStartDate(row, locale) {',
                    "    const [year, month, day] = row.start_date.split('/').map(Number);",
                    "    return new Intl.DateTimeFormat(locale, { day: 'numeric', month: 'short', year: 'numeric', timeZone: 'UTC' }).format(new Date(Date.UTC(year, month - 1, day)));",
                    '}',
                ] : []),
                '',
                'export default {',
                '    components: { DatatableCard },',
                '    data() {',
                `        return { feedback: '', datatableProps: ${serialized} };`,
                '    },',
                '    methods: {',
                '        showEmployee(row) { this.feedback = `Employee: ${row.name}`; },',
                '        showSelectedRows() { this.feedback = `Selected IDs: ${this.$refs.datatable.getSelectedRows().join(", ") || "none"}`; },',
                '    },',
                '};',
                '<' + '/script>',
            );
            return lines.join('\n');
        },
    },
    methods: {
        applySettings() {
            if (!this.hasVisibleColumn) {
                return;
            }
            this.applied = { ...this.settings, columns: this.settings.columns.map(column => ({ ...column })) };
            this.rowFeedback = '';
            this.copyFeedback = '';
            this.tableVersion++;
        },
        resetSettings() {
            this.settings = defaultSettings();
            this.applySettings();
        },
        loadEmployees() {
            this.$refs.datatable.loadData();
        },
        onRowClick(employee) {
            this.rowFeedback = `row-click: ${employee.name} — ${employee.position}, ${employee.office}`;
        },
        onInspect(employee) {
            this.rowFeedback = `Inspect: ${employee.name} — ${employee.position}, ${employee.office}. Demo only.`;
        },
        onFlag(employee) {
            this.rowFeedback = `Flag: ${employee.name}. Demo only, no record was changed.`;
        },
        showSelectedRows() {
            const selected = this.$refs.datatable.getSelectedRows();
            this.rowFeedback = `Selected IDs: ${selected.length ? selected.join(', ') : 'none'}`;
        },
        async copyConfiguration() {
            try {
                await navigator.clipboard.writeText(this.configurationExample);
                this.copyFeedback = 'Vue example copied.';
            } catch {
                this.$refs.configuration.focus();
                this.$refs.configuration.select();
                this.copyFeedback = 'Example selected. Press Ctrl+C or Cmd+C to copy.';
            }
        },
    },
};
</script>
